for _ in range(int(input())):
	covered = {}
	n = int(input())
	s = input()
	difference = float('inf')
	for i in range(n - 1, -1, -1):
		if s[i] in covered:
			difference = min(difference, covered[s[i]] - i)
		covered[s[i]] = i
	if difference == float('inf'):
		print(0)
		continue
	print(n - difference)
